// bedient hoechstens n Gaeste, liefert die Anzahl
public static int bediene(Queue q, int n) {
    int anzahl = 0;
    while (anzahl < n && !q.isEmpty()) {
        String gast = (String) q.dequeue();
        println(gast + " wird bedient");
        anzahl++;
    }
    return anzahl;
}

public static int gesamtHeilung(Stack rucksack) {
    Stack hilf = new Stack();
    int summe = 0;
    while (!rucksack.isEmpty()) {  // abbauen
        int h = (Integer) rucksack.pop();
        summe = summe + h;
        hilf.push(h);
    }
    while (!hilf.isEmpty()) {  // zurueck
        rucksack.push(hilf.pop());
    }
    return summe;
}
